// Synthetic E2E-04 orchestration. All business writes use existing application adapters.
import {randomUUID as uid} from 'node:crypto';
import {quantityFixture} from './h2-quantities-fixtures.ts';
import {cancellationFixture,cancellationSchedule,cancellationApplication} from './h5-017-g-cancellation-fixtures.ts';
import {confirmationFixture} from './h4-confirmation-fixtures.ts';
import {scopedReality} from './h4-reality-fixtures.ts';
import {paymentFixture} from './h3-payment-fixtures.ts';
import {closureCommands} from './h5-closure-fixtures.ts';
import {jointCommands} from './h5-joint-closure-fixtures.ts';
import {read,write,type Fifth} from './h5-018-fifth-isolated.ts';
import {canonicalCommercial} from '../../src/domain/commercial-progress.ts';
import {fingerprintHumanApprovalMaterial as mf,fingerprintHumanApprovalPart as pf,type HumanApprovalMaterial} from '../../src/infrastructure/postgres/h0-011-adapter.ts';
import type {RefundCommand,RefundAuthorization} from '../../src/domain/refund.ts';
export {read,write};
export async function e2e04Fixture(h:Fifth){
 const booking=await quantityFixture(h);await h.booking.apply(await h.auth(),write,booking.q);
 const bid=booking.q.bookingId;
 const identity=(await h.observer`select accepter_id::text id,designation_id::text designation from crm_private.b03_acceptances where acceptance_id=${booking.q.acceptanceId}::uuid`)[0]!;
 const proof=async(claim:string,coverage=bid,at=new Date().toISOString())=>{const e=h.req('evidence',{claim,coverage,certainty:'reviewed',source_kind:'manual'},bid,'booking');await h.evidence.apply(await h.auth(),write,{...e,occurredAt:at,coverage});return e.targetId;};
 const context={accepterId:String(identity.id),designationId:String(identity.designation),mid:booking.detail.services[0]!.contributions[0]!.modalityId,other:booking.detail.services[1]!.contributions[1]!.modalityId,proof:(claim:string,_coverage:string,at:string)=>booking.proof(claim,at)};
 const c=await cancellationFixture(h,{existing:{f:context,b:booking.q,detail:booking.detail},scopeKind:'service'});
 const otherConf=await confirmationFixture(h,c.conf.b,1);
 const realityView=(await h.reality.read(await h.auth(),read,bid))!;
 const otherScopes=realityView.scopes.filter(s=>s.serviceId===booking.detail.services[1]!.id).map(s=>({serviceId:String(s.serviceId),nightId:s.nightId as string|null,contributionId:s.contributionId as string|null,dimension:s.dimension as 'quantity',start:'0',amount:String(s.current)}));
 const reality=await scopedReality(h,otherConf,otherScopes);
 // Accredited prior performance, explicitly reviewed as reality; never invent prior confirmation.
 await reality.run(await reality.command('perform'));
 const schedule=await cancellationSchedule(h,c,'1200.12');
 const payment=await paymentFixture(h,'400.00',true,'400.00');
 await h.payments.apply(await h.auth(),write,await payment.attest({...payment.detect,detection:{...payment.detect.detection!,bookingId:bid}}));
 await h.payments.apply(await h.auth(),write,await payment.receive());
 const reconciliation=await payment.attest({...await payment.propose(2,'200.00'),bookingId:bid,scheduleId:schedule.sid});
 await h.payments.apply(await h.auth(),write,reconciliation);await h.payments.apply(await h.auth(),write,await payment.verify(reconciliation));
 const id=uid(),view=()=>h.auth().then(a=>h.refunds.read(a,read,bid,id));
 const hash=c.conf.hash;
 const attest=async(q:RefundCommand)=>({...q,evidenceId:await payment.proof(id,'refund:'+q.action+':'+await hash(Object.fromEntries(Object.entries(q).filter(([k,v])=>!['operationId','evidenceId'].includes(k)&&v!==undefined))),'reviewed','manual',q.at)});
 const command=async(action:RefundCommand['action'],changes:Partial<RefundCommand>={})=>attest({action,operationId:uid(),refundId:id,bookingId:bid,expectedRevision:(await view())?.revision??0,sourceRef:'SYNTHETIC E2E04 exact source',reason:'SYNTHETIC E2E04 reviewed fact',at:new Date().toISOString(),evidenceId:uid(),...changes});
 const request=()=>command('request',{requesterId:context.accepterId,paymentIds:[payment.paymentId],cause:'provider',affectedScope:c.scope.id});
 const determine=async()=>command('determine',{determinationId:c.did,determinationRevision:(await c.see()).revision});
 const portion=async(amount:string,start='0.00')=>{const funds=(await h.allocations.read(await h.auth(),read,payment.paymentId))!;return {paymentId:payment.paymentId,reconciliationId:reconciliation.reconciliationId!,start,amount,paymentRevision:funds.paymentRevision,fundRevision:funds.revision};};
 const authorization=async(amount='200.00',changes:Partial<RefundAuthorization>={})=>command('authorize',{authorization:{amount,recipientId:context.accepterId,method:'bank_transfer',cause:'provider',effect:'refund-contractual-right',conditions:'SYNTHETIC exact S1 right; no bank operation',portions:[await portion(amount)],...changes}});
 const approveRefund=async(q:RefundCommand)=>{const proposal='h6004-proposal-'+uid(),decision='h6004-decision-'+uid(),part='h6004-part-'+uid(),reserve='h6004-reserve-'+uid(),a=q.authorization!;
  const material:HumanApprovalMaterial={action:'refund-authorize',contentVersion:'h4-015-v1',content:canonicalCommercial(q),recipient:{state:'value',value:a.recipientId},amount:{state:'value',value:a.amount},conditions:{state:'value',value:a.conditions},scope:h.scope,effect:'authorize-refund-fact',destination:{state:'value',value:a.recipientId},parts:[{partId:part,action:'refund-authorize',contentVersion:'h4-015-v1',content:canonicalCommercial(q),recipient:{state:'value',value:a.recipientId},amount:{state:'value',value:a.amount},conditions:{state:'value',value:a.conditions},scope:h.scope,effect:'authorize-refund-fact'}]};
  await h.tte.propose(await h.auth(),write,proposal,'human',material);await h.tte.decide(await h.auth(),write,'h6004-decide-'+uid(),proposal,decision,'approved','SYNTHETIC exact prospective approval',mf(material));
  return {proposal,decision,reserve,execute:async(input=q)=>h.tte.authorizeRefund(await h.auth(),write,reserve,proposal,decision,part,mf(material),pf(material.parts[0]!),material,input)};
 };
 const movement=async(amount:string,start='0.00')=>command('record',{movement:{identity:{source:'SYNTHETIC H6004 bank double',account:'SYNTHETIC account',externalId:uid()},amount,recipientId:context.accepterId,method:'bank_transfer',occurredAt:new Date().toISOString(),reference:'SYNTHETIC evidenced outflow',portions:[await portion(amount,start)]}});
 const run=async(q:RefundCommand)=>h.refunds.apply(await h.auth(),write,q);
 const provider=async()=>{const original=h.req('communication',{direction:'outgoing',channel:'synthetic-manual',recipient_ref:c.conf.source.id,coverage:c.conf.service.id,initial_fact:'none'},bid,'booking');await h.evidence.apply(await h.auth(),write,original);const evidence=await proof('SYNTHETIC request received by provider double',c.conf.service.id);const sent=h.req('communication_fact',{fact_kind:'sent',evidence_id:evidence,party_ref:c.conf.source.id,coverage:c.conf.service.id},bid,'booking');await h.evidence.apply(await h.auth(),write,{...sent,originalId:original.targetId});return c.m.command('provider',{partIds:[c.m.partId],commitment:'SYNTHETIC S1 only cancellation requested',recordId:sent.targetId});};
 const response=async(result='accepted')=>c.m.command('response',{partIds:[c.m.partId],source:c.conf.source,recordId:await c.conf.record(),happenedAt:result==='ambiguous'?'2026-10-03T10:00:00Z':'2026-10-03T11:00:00Z',result,coverage:{[c.m.partId]:{cancelled:true}},alternatives:[]});
 const determineRight=async(pending=false)=>{const q=await c.command();return c.command({expectedRevision:(await c.see())?.revision??0,facts:{...q.facts!,cause:'provider',base:await c.base(pending?null:'200.00')}});};
 const obligation=()=>h.auth().then(a=>h.obligations.read(a,read,bid,schedule.sid));
 const adjustment=async()=>cancellationApplication(h,c,schedule.sid,(await obligation())!.current.snapshot.parts.map(p=>({...p,amount:p.slot==='initial'?'400.06':'600.06'})));
 const closures=await closureCommands(h,bid),joint=await jointCommands(h,bid);
 const flags=booking.detail.services.map(s=>({serviceId:s.id,suplido:false,deposit:false,ownEconomics:false,reason:'SYNTHETIC declared scope; other economic obligations remain assessed separately'}));
 const assessRefund=async(satisfied=false)=>{const v=await closures.view();const action=v.assessments.economic?'evaluate':'open';return closures.run(await closures.command('economic',{refunds:satisfied?'satisfied':'pending'},{action,serviceApplicability:flags}));};
 const unaffected=async()=>({accepted:(await h.observer`select detail from crm_private.b04_bookings where booking_id=${bid}::uuid`)[0]!.detail,services:await h.observer`select to_jsonb(s) row from crm_private.b04_services s where booking_id=${bid}::uuid and service_id<>${c.scope.id}::uuid order by service_id`,contributions:await h.observer`select to_jsonb(s) row from crm_private.b04_contributions s where booking_id=${bid}::uuid and service_id<>${c.scope.id}::uuid order by contribution_id`,nights:await h.observer`select to_jsonb(s) row from crm_private.b04_nights s where booking_id=${bid}::uuid and service_id<>${c.scope.id}::uuid order by night_id`});
 const snapshot=async()=>({unaffected:await unaffected(),booking:await h.booking.read(await h.auth(),read,bid),modification:await c.m.see(),determination:await c.see(),refund:await view(),obligation:await obligation(),funds:await h.allocations.read(await h.auth(),read,payment.paymentId),reality:await reality.read(),closures:await closures.view()});
 return {booking,bid,c,context,payment,reconciliation,schedule,id,view,command,attest,request,determine,authorization,approveRefund,movement,run,provider,response,determineRight,obligation,adjustment,closures,joint,flags,assessRefund,snapshot,unaffected};
}
